Step.Calculation:
JSONSetElement ( "{}" ;
	[ "sifra" ; $sifra ; JSONString ] ;
	[ "primkaID" ; $primkaID ; JSONString ] ;
	[ "stavkaID" ; $stavkaID ; JSONString ] ;
	[ "kolicina" ; $kolicina ; JSONString ] ;
	[ "traceID" ; $traceID ; JSONString ]
)

Message.Calculation:
Let ( [
	~errs = JSONGetElement ( $r ; "messages.error" ) ;
	~n = ValueCount ( JSONListKeys ( ~errs ; "" ) )
] ;
	While ( [ ~i = 0 ; ~out = "" ] ; ~i < ~n ; [ ~out = List ( ~out ; JSONGetElement ( ~errs ; "[" & ~i & "].text" ) ) ; ~i = ~i + 1 ] ; ~out )
)

Step.Calculation:
JSONSetElement ( "{}" ;
	[ "stavkaID" ; $stavkaID ; JSONString ] ;
	[ "mode" ; "nabavna" ; JSONString ] ;
	[ "amount" ; GetAsNumber ( $amount ) ; JSONNumber ] ;
	[ "basis" ; "total" ; JSONString ] ;
	[ "traceID" ; $traceID ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "stavkaID" ; $stavkaID ; JSONString ] ;
	[ "mode" ; "prodajna" ; JSONString ] ;
	[ "amount" ; GetAsNumber ( $amount ) ; JSONNumber ] ;
	[ "basis" ; "total" ; JSONString ] ;
	[ "traceID" ; $traceID ; JSONString ]
)

Value.Calculation:
If ( not IsEmpty ( $selT ) or epSQLResultRowCount ( "dispT" ) = 0 ;
	0 ;
	GetAsNumber ( epSQLResult ( 0 ; 0 ; "dispT" ) )
)

If ( not IsEmpty ( $selR ) or epSQLResultRowCount ( "dispR" ) = 0 ;
	0 ;
	GetAsNumber ( epSQLResult ( 0 ; 0 ; "dispR" ) )
)

If ( not IsEmpty ( $selT ) or epSQLResultRowCount ( "dispT" ) = 0 ;
	0 ;
	GetAsNumber ( epSQLResult ( 0 ; 0 ; "dispT" ) )
)

If ( not IsEmpty ( $selR ) or epSQLResultRowCount ( "dispR" ) = 0 ;
	0 ;
	GetAsNumber ( epSQLResult ( 0 ; 0 ; "dispR" ) )
)
